<?php declare(strict_types=1);require dirname(__DIR__).'/includes/bootstrap.php';if(admin())redirect('/admin/dashboard.php');$error=null;$debug=null;if(is_post()){verify_csrf();try{if(input('action')==='request'){$debug=create_admin_otp(trim((string)input('mobile')));}elseif(input('action')==='verify'&&verify_admin_otp(trim((string)input('mobile')),trim((string)input('otp'))))redirect('/admin/dashboard.php');else $error='Invalid or expired OTP.';}catch(Throwable $e){$error=$e->getMessage();}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff OTP sign in</title><link rel="stylesheet" href="<?=e(app_url('/assets/css/style.css'))?>"></head><body class="login-page"><section class="login-card"><h1>Passwordless staff sign in</h1><p>Only approved KYC staff may request a six-digit OTP.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><?php if($debug):?><div class="alert">Development OTP: <?=e($debug)?></div><?php endif?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="request"><div class="field"><label>Registered mobile</label><input name="mobile" required></div><button class="btn">Send OTP</button></form><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="verify"><div class="field"><label>OTP</label><input name="otp" inputmode="numeric" pattern="\d{6}" maxlength="6" required></div><input type="hidden" name="mobile" value="<?=e($_SESSION['_otp_mobile']??'')?>"><button class="btn">Verify and sign in</button></form><a href="<?=e(app_url('/admin/login.php'))?>">Use password login</a></section></body></html>
